import { sharedOrganizationWorkflowTranslations } from './sharedOrganizationWorkflowTranslations.js';

const DK_TERMS_HTML = [
  '<h2>1. Tjenesteudbyder og anvendelsesområde</h2>',
  '<p>Disse interne regler (Reglerne) regulerer brugen af Tutlio-platformen (Platformen). Tjenesteudbyderen er MB Tutlio. Ved at bruge Platformen, herunder ved registrering, login, planlægning af lektioner, betalinger og abonnementer, accepterer du disse Regler og Privatlivspolitikken. Reglerne er i overensstemmelse med bestemmelserne i Republikken Litauens civillovbog samt lovgivningen om forbrugerbeskyttelse, elektroniske tjenester og betalingstjenester.</p>',
  '<h2>2. Registrering og konto</h2>',
  '<p>For at bruge Platformen skal du registrere dig og acceptere Privatlivspolitikken og disse Brugervilkår. Du forpligter dig til at give korrekte og fuldstændige oplysninger og til at opdatere dem, når de ændres. Din konto er personlig. Beskyt din adgangskode, og videregiv den ikke til tredjeparter. Du er ansvarlig for handlinger, der udføres via din konto.</p>',
  '<h2>3. Abonnement og betalinger for tutorer og organisationer</h2>',
  '<p>Tutorer og organisationer betaler for brugen af Platformen efter en SaaS-model. Det individuelle standardabonnement koster 20 EUR om måneden, medmindre en anden individuelt aftalt B2B-ordning gælder. Abonnementsbetalinger behandles af tredjepartsbetalingspartnere såsom Stripe.</p>',
  '<ul><li><strong>Opsigelse:</strong> Du kan opsige dit abonnement under Indstillinger eller via partnerens selvbetjeningsportal. Efter opsigelsen er abonnementet gyldigt indtil udgangen af den aktuelle betalte periode. Derefter begrænses adgangen til betalingsfunktioner.</li><li><strong>Skift til en anden plan:</strong> Du kan skifte til en anden plan, for eksempel fra månedlig til årlig, efter den procedure, der vises på Platformen. Forholdsmæssige beregninger gælder.</li><li><strong>Refusioner:</strong> Refusionspolitikken følger Republikken Litauens lov om forbrugerbeskyttelse. Konkrete tilfælde vurderes individuelt ved henvendelse til info@tutlio.lt.</li></ul>',
  '<h2>4. Organisationer og virksomheder</h2>',
  '<p>Platformen giver organisationer såsom lektiehjælpscentre, skoler og virksomheder mulighed for at oprette konti og administrere flere tutorer og elever centralt. Abonnementspriser, gebyrer for betalingsbehandling og vilkår for organisationer kan afvige fra dem, der gælder for individuelle tutorer. De konkrete vilkår aftales individuelt ved indgåelse af en tjenesteydelsesaftale.</p>',
  '<h2>5. Aflysning af lektioner og aflysningsregler</h2>',
  '<p>Vilkårene for aflysning af lektioner, såsom hvor lang tid der er til lektionen, og aflysningsgebyrets procentsats, fastsættes direkte af tutoren og/eller organisationen. Oplysningerne vises i elevens profil på Platformen. Hvis en lektion aflyses rettidigt efter de fastsatte regler, opkræves der muligvis ikke noget gebyr. Ved sen aflysning kan det fastsatte procentvise gebyr for lektionen blive opkrævet.</p>',
  '<h2>6. Betalinger for lektioner mellem tutoren og eleven eller forældrene</h2>',
  '<p>Betaling for konkrete lektioner sker direkte for de tjenester, som tutoren eller organisationen leverer. Til betalingsbehandling bruger Platformen licenserede tredjepartsudbydere af betalingstjenester såsom Stripe til internationale kortbetalinger eller UAB Perlas Finance til lokale netbankbetalinger.</p>',
  '<ul><li><strong>Status som handelsagent:</strong> MB Tutlio leverer teknisk infrastruktur og fungerer ved betalinger udelukkende som tutorens/organisationens autoriserede handelsagent med henblik på at opkræve midler. Ved at betale via Platformen opfylder eleven eller elevens forældre/værger sin økonomiske forpligtelse over for tutoren/organisationen.</li><li><strong>Betalingsmodel:</strong> Betaleren, dvs. eleven eller forældrene, betaler lektionsprisen og Platformens administrations- eller transaktionsgebyr, som tydeligt vises i betalingsvinduet, inden betalingen gennemføres. Gebyret kan variere afhængigt af den valgte betalingsmetode eller B2B-aftalen.</li><li><strong>Betalingsmåder:</strong> Engangsbetaling for hver lektion, forudbetalte lektionspakker med flere lektioner eller månedlige fakturaer for lektioner, der er gennemført i rapporteringsperioden.</li></ul>',
  '<p>Tutoren/organisationen, og ikke MB Tutlio, er direkte ansvarlig over for eleven for leveringen og kvaliteten af undervisningen samt opfyldelsen af sine forpligtelser.</p>',
  '<h2>7. Yderligere funktioner</h2>',
  '<p>Platformen tilbyder yderligere funktioner såsom kalendersynkronisering med Google Kalender, en venteliste og automatiske e-mailpåmindelser om kommende lektioner og betalinger. Adgangen til disse funktioner kan afhænge af organisationens abonnementsplan.</p>',
  '<h2>8. Databeskyttelse og overholdelse af GDPR</h2>',
  '<p>Du kan finde detaljerede oplysninger om databehandlingen i Privatlivspolitikken.</p>',
  '<h3>8.1. Den dataansvarliges og databehandlerens ansvar</h3>',
  '<p>I henhold til GDPR fungerer tutoren/organisationen som dataansvarlig ved behandling af elevers personoplysninger, mens MB Tutlio udelukkende fungerer som databehandler og leverer cloudplatformens infrastruktur. Hver part har klart definerede ansvarsområder.</p>',
  '<p><strong>MB Tutlios ansvar som databehandler:</strong> at levere Platformens infrastruktur og teknisk support; at gennemføre organisatoriske og tekniske sikkerhedsforanstaltninger, herunder kryptering, adgangskontrol og sikkerhedskopiering; at sende automatiske meddelelser i nøje overensstemmelse med tutorens/organisationens indstillinger; at underrette Kunden om brud på persondatasikkerheden senest inden for 72 timer i henhold til GDPR artikel 33; at yde teknisk bistand til den dataansvarlige ved udøvelsen af registreredes rettigheder, herunder adgang, sletning og eksport.</p>',
  '<p><strong>Tutorens/organisationens ansvar som dataansvarlig:</strong> Retsgrundlag: at have et retsgrundlag for behandling af alle elevers personoplysninger, der indtastes på Platformen, såsom samtykke, kontrakt eller legitim interesse; Information: at informere elever og deres forældre/værger om databehandlingen på Platformen og give et link til Tutlios Privatlivspolitik; Oplysningernes korrekthed: at sikre, at oplysninger, der indtastes på Platformen, er korrekte, fuldstændige og ajourførte; Registreredes rettigheder: selvstændigt at besvare elevers anmodninger om behandling af deres oplysninger ved hjælp af de værktøjer, Platformen stiller til rådighed; Samtykkestyring: at indhente og administrere de nødvendige samtykker, for eksempel forældres samtykke til at arrangere lektioner for mindreårige.</p>',
  '<h3>8.2. Tutorens/organisationens yderligere forpligtelser</h3>',
  '<p>Ved at bruge Platformen og indtaste elevers personoplysninger forpligter tutoren/organisationen sig til at overholde alle GDPR-krav og Republikken Litauens databeskyttelseslovgivning, straks underrette MB Tutlio om observerede datasikkerhedshændelser eller brud, kun bruge Platformen til lovlige formål og ikke videregive loginoplysninger til tredjeparter.</p>',
  '<h3>8.3. Databehandleraftale (DPA)</h3>',
  '<p>Til B2B-kunder, dvs. organisationer, der indgår tjenesteydelsesaftaler, leverer MB Tutlio et særskilt bilag med en databehandleraftale (DPA), som detaljeret beskriver begge parters forpligtelser, sikkerhedsforanstaltninger for infrastrukturen, lister over underdatabehandlere og andre GDPR-krav. Den generelle DPA er tilgængelig på tutlio.lt/dpa.</p>',
  '<h2>9. Forbudte aktiviteter og ansvarsbegrænsning</h2>',
  '<p>Det er forbudt at bruge Platformen til ulovlige formål, misbruge konti, sprede skadelig software eller på anden måde overtræde lovgivningen. Tjenesteudbyderen forbeholder sig ret til at begrænse eller afslutte adgangen ved overtrædelse af disse Regler. For at sikre virksomhedens bæredygtighed er MB Tutlio ikke ansvarlig for indirekte tab eller tabt fortjeneste, og det maksimale ansvar er begrænset af vilkårene på Platformen eller i B2B-aftalen.</p>',
  '<h2>10. Intellektuel ejendom og ændringer af tjenesterne</h2>',
  '<p>Platformens indhold, design, software og varemærke tilhører Tjenesteudbyderen. Tjenesteudbyderen kan forbedre og ændre Platformens funktioner, priser eller Regler. Eksisterende kunder informeres på forhånd om væsentlige ændringer via e-mail eller en meddelelse på Platformen.</p>',
  '<h2>11. Tvister og lovvalg</h2>',
  '<p>Tvister løses ved forhandling. Uoverensstemmelser kan behandles ved domstolene i Republikken Litauen. Ufravigelige regler om forbrugerbeskyttelse gælder for forbrugere, dvs. elever og forældre. Disse Regler er underlagt Republikken Litauens ret.</p>',
  '<h2>12. Kontakt</h2>',
  '<p>Spørgsmål om disse Regler, privatliv, betalinger eller teknisk support kan sendes til MB Tutlio på info@tutlio.lt.</p>',
].join('');

const DK_PRIVACY_HTML = [
  '<h2>1. Generelle bestemmelser</h2>',
  '<p>Denne privatlivspolitik (Politikken) forklarer, hvordan MB Tutlio (virksomhedskode 307617263), som driver Tutlio-platformen (Tjenesteudbyderen, vi), indsamler, bruger og beskytter personoplysninger. Vi handler i overensstemmelse med Republikken Litauens lovgivning: databeskyttelsesforordningen (GDPR) (EU 2016/679), Republikken Litauens lov om retlig beskyttelse af personoplysninger, lovgivningen om elektroniske tjenester og elektronisk kommunikation samt anden gældende lovgivning.</p>',
  '<h2>2. Roller som dataansvarlig og databehandler</h2>',
  '<p>Ved levering af B2B-cloudtjenester er databeskyttelsesrollerne klart adskilt i overensstemmelse med GDPR: Tutoren/organisationen (Platformens kunde) fungerer udelukkende som dataansvarlig for alle personoplysninger om elever og deres forældre/værger, der indtastes på Platformen. MB Tutlio fungerer udelukkende som databehandler efter GDPR artikel 28 for elevers personoplysninger og behandler dem kun efter Kundens instruktioner. MB Tutlio fungerer kun som dataansvarlig for registrerings- og faktureringsoplysninger om tutorerne/organisationerne selv, dvs. sine direkte B2B-kunder.</p>',
  '<p><strong>2.1.</strong> Tutoren/organisationen er som dataansvarlig ansvarlig for: retsgrundlag, information, oplysningernes korrekthed og registreredes rettigheder.</p>',
  '<p><strong>2.2.</strong> MB Tutlio behandler som databehandler elevers oplysninger med følgende formål: levering af Platformen, sikkerhed, automatiserede processer og betalingsbehandling.</p>',
  '<h2>3. Hvilke oplysninger vi indsamler</h2>',
  '<p><strong>Kundernes registrerings- og kontooplysninger:</strong> e-mailadresse, for- og efternavn, telefonnummer og adgangskode, der opbevares krypteret, dvs. som en hash. <strong>Betalingsoplysninger:</strong> betalingshistorik og betalingsstatus for lektioner. Betalingskort- eller bankoplysninger behandles kun via licenserede partnere, Stripe eller UAB Perlas Finance. MB Tutlio ser eller opbevarer ikke fulde kortoplysninger eller loginoplysninger til netbank. <strong>Abonnementsoplysninger:</strong> abonnementsplan, gyldighedsdato og brug af prøveperiode. <strong>Lektions- og skemaoplysninger:</strong> lektionstidspunkter, emner, noter, aflysninger og udsendelse af påmindelser. <strong>Elevoplysninger indtastet af tutoren:</strong> elevnavne, e-mailadresser, telefonnumre og betalingsoplysninger om forældre/værger. <strong>Tekniske oplysninger:</strong> IP-adresse, browsertype og logintidspunkter af hensyn til legitime interesser såsom systemsikkerhed og forebyggelse af misbrug.</p>',
  '<h2>4. Brug af Google API-data og Google API Limited Use Policy</h2>',
  '<p>For at gøre skemastyringen nem gør Platformen det muligt for brugere at forbinde deres konto med Google Kalender via OAuth-godkendelse. Vi anmoder kun om læse- og skriveadgang til dine begivenheder i Google Kalender, så lektioner, der planlægges på Platformen, kan synkroniseres med din personlige kalender. Dine Google-kalenderoplysninger bruges udelukkende til at sikre tovejssynkronisering af kalenderen. Vi overfører, sælger eller deler ikke dine Google-brugeroplysninger med tredjeparter, herunder annoncenetværk eller andre kommercielle partnere. Tutlios brug og overførsel til andre applikationer af oplysninger modtaget fra Google API\'er overholder nøje Google API Services User Data Policy, herunder kravene om begrænset brug (Limited Use).</p>',
  '<h2>5. Formål og retsgrundlag efter GDPR artikel 6</h2>',
  '<p>Vi behandler oplysninger for at opfylde en aftale, herunder administrere konti, lektioner og betalinger; for legitime interesser, herunder platformsikkerhed og fakturering; med dit samtykke, hvor loven kræver det; og for at overholde retlige forpligtelser, herunder bogføring. Vi bruger e-mail til at informere om betalinger og aflysninger. Aflysningsreglerne er beskrevet i Platformens Brugervilkår.</p>',
  '<h2>6. Opbevaring og sikkerhed</h2>',
  '<p>Vi opbevarer kun oplysninger, så længe det er nødvendigt for at opfylde aftalen og overholde lovkrav såsom bogføringskrav. Vi anvender passende tekniske og organisatoriske foranstaltninger, herunder kryptering under overførsel og i hvile, adgangskontrol og automatiske sikkerhedskopier, for at beskytte oplysninger mod uautoriseret adgang, tab eller misbrug.</p>',
  '<h3>6.1. Underdatabehandlere</h3>',
  '<p>MB Tutlio bruger nøje udvalgte underdatabehandlere, der overholder GDPR, til at levere cloud- og betalingsinfrastruktur: Supabase Inc.; Stripe, Inc.; UAB Perlas Finance; Resend (Zernonia, Inc.). Alle underdatabehandlere forpligter sig til kun at behandle personoplysninger efter vores instruktioner og anvende de strengeste sikkerhedsstandarder, herunder standardkontraktbestemmelser (SCC) ved overførsel af oplysninger uden for EU.</p>',
  '<h2>7. Dine rettigheder efter GDPR</h2>',
  '<p>Kontakt os på info@tutlio.lt for at udøve dine databeskyttelsesrettigheder. Hvis du er elev eller forælder/værge til en elev, skal du først kontakte din tutor eller skole direkte om oplysninger, som vedkommende har indtastet på Platformen. Tutoren eller skolen er din dataansvarlige. Vi hjælper den dataansvarlige teknisk med at gennemføre dine rettigheder, men det primære ansvar ligger hos din tutor/organisation. Hvis du er tutor/organisation, kan du selv administrere, rette, slette eller eksportere elevers oplysninger via Platformens indstillinger. Når der er behov for teknisk hjælp, hjælper vi dig med at gennemføre de registreredes rettigheder.</p>',
  '<h3>7.1. Underretning om brud på persondatasikkerheden</h3>',
  '<p>Hvis der sker et brud på persondatasikkerheden, underretter vi den dataansvarlige, dvs. tutoren/organisationen, senest 72 timer efter, at vi er blevet bekendt med bruddet. Den dataansvarlige er ansvarlig for eventuel yderligere underretning af registrerede eller tilsynsmyndigheden (VDAI), som GDPR kræver.</p>',
  '<h2>8. Cookies og analyse</h2>',
  '<p>Vi bruger kun nødvendige tekniske cookies, som kræves til brugerlogin, opretholdelse af sessioner og sikker drift af Platformen. Vi bruger ikke tredjepartscookies til markedsføring på Platformen uden særskilt samtykke.</p>',
  '<h2>9. Ændringer</h2>',
  '<p>Denne Politik kan blive opdateret, efterhånden som tjenesterne forbedres. Vi informerer eksisterende kunder om væsentlige ændringer via e-mail eller en meddelelse på Platformen. Ved fortsat brug af tjenesterne efter offentliggørelsen af ændringerne accepterer du den opdaterede Privatlivspolitik. En databehandleraftale (DPA) gælder desuden for B2B-kunder.</p>',
].join('');

const DK_DPA_HTML = [
  '<p><strong>Bemærkning:</strong> Denne databehandleraftale (DPA) er en integreret del af tjenesteydelsesaftalen, hvis en sådan er indgået, Tutlio-platformens Brugervilkår og Privatlivspolitik. Den gælder for alle tutorer og organisationer, der bruger Tutlio-platformen og behandler elevers personoplysninger.</p>',
  '<h2>1. Parter og definitioner</h2>',
  '<h3>1.1. Parter og roller</h3>',
  '<p>Denne databehandleraftale (DPA\'en) indgås mellem MB Tutlio (Tjenesteudbyderen eller Platformen), som leverer Tutlio-platformens tjenester, og tutoren/organisationen (Kunden), som bruger Platformen til at administrere elevers oplysninger og organisere lektioner. Parterne er udtrykkeligt enige om, at Kunden i henhold til databeskyttelsesforordningen (GDPR) udelukkende fungerer som dataansvarlig, når personoplysninger behandles på Platformen, mens MB Tutlio udelukkende fungerer som databehandler efter GDPR artikel 28.</p>',
  '<h3>1.2. Definitioner</h3>',
  '<p><strong>GDPR</strong> betyder databeskyttelsesforordningen (EU 2016/679). <strong>Personoplysninger</strong> betyder enhver oplysning om en fysisk person, såsom en elev eller forælder/værge, hvis identitet er kendt eller kan fastslås. <strong>Dataansvarlig</strong> betyder den fysiske eller juridiske person, Kunden, der fastlægger formålene med og midlerne til behandlingen af personoplysninger. <strong>Databehandler</strong> betyder den fysiske eller juridiske person, MB Tutlio, der udelukkende behandler personoplysninger på vegne af og efter instruktion fra den dataansvarlige. <strong>Registreret</strong> betyder den fysiske person, såsom en elev eller forælder/værge, hvis personoplysninger behandles. <strong>Underdatabehandler</strong> betyder en tredjepart, som Tjenesteudbyderen bruger til databehandling, såsom Supabase, Stripe eller Perlas Finance.</p>',
  '<h2>2. Databehandlingens omfang og formål</h2>',
  '<h3>2.1. Behandlede oplysninger</h3>',
  '<p>På Platformen kan følgende personoplysninger om elever og forældre/værger behandles efter Kundens instruktioner: for- og efternavn; e-mailadresse; telefonnummer; valgfrit alder og klasse; invitationskoder; lektionshistorik, herunder datoer, tidspunkter, emner og noter; betalingsoplysninger, herunder beløb, status og betalingsfrister; oplysninger om forælder/værge, hvis betaleren ikke er eleven: navn og e-mailadresse.</p>',
  '<h3>2.2. Behandlingens formål</h3>',
  '<p>Oplysninger behandles med følgende formål: levering af Platformens tjenester, herunder lektionsplanlægning, kalenderstyring og udsendelse af påmindelser; betalingsadministration, herunder behandling af lektionsbetalinger og generering og udsendelse af fakturaer; kommunikation, herunder udsendelse af automatiske meddelelser; bogføring, herunder føring af regnskabsmateriale som krævet ved lov; forbedring af Platformen ved brug af anonym statistik til at forbedre Platformens tjenester.</p>',
  '<h3>2.3. Behandlingens varighed</h3>',
  '<p>Oplysninger opbevares, så længe tjenesteydelsesaftalen eller kontobrugen mellem Kunden og Platformen er gældende; regnskabsmateriale, herunder betalinger og fakturaer, opbevares i 10 år som krævet af bogføringslovgivningen; efter aftalens ophør eller sletning af kontoen opbevares oplysninger i op til 30 dage, medmindre Kunden anmoder om tidligere sletning eller eksport af oplysninger.</p>',
  '<h2>3. Parternes forpligtelser og ansvar</h2>',
  '<h3>3.1. Tjenesteudbyderens forpligtelser som databehandler</h3>',
  '<p>Tjenesteudbyderen forpligter sig til: kun at behandle oplysninger efter Kundens instruktioner; at gennemføre passende tekniske og organisatoriske sikkerhedsforanstaltninger; at underrette Kunden om brud på persondatasikkerheden senest 72 timer efter at være blevet bekendt med dem; at hjælpe Kunden med at gennemføre registreredes rettigheder; kun at bruge godkendte underdatabehandlere; at returnere eller slette oplysninger efter aftalens ophør efter Kundens valg; at tillade revisioner; og ikke at overføre oplysninger uden for EU/EØS uden passende garantier.</p>',
  '<h3>3.2. Kundens forpligtelser som dataansvarlig</h3>',
  '<p>Kunden forpligter sig til: at have et retsgrundlag for behandlingen af alle oplysninger, der indtastes på Platformen; at informere de registrerede; at indhente de nødvendige samtykker; at sikre oplysningernes korrekthed og overholde princippet om dataminimering; selvstændigt at besvare anmodninger fra registrerede; at bruge Platformen ansvarligt, ikke videregive adgang til tredjeparter og beskytte loginoplysninger.</p>',
  '<h2>4. Underdatabehandlere</h2>',
  '<h3>4.1. Godkendte underdatabehandlere</h3>',
  '<p>Kunden giver Tjenesteudbyderen en generel tilladelse til at bruge følgende underdatabehandlere: Supabase Inc. til databasehosting og -administration, EU AWS eu-central-1, overholder GDPR, ISO 27001; Stripe, Inc. til betalingsbehandling, USA/EU med brug af SCC, PCI DSS Level 1; UAB Perlas Finance til open banking- og betalingsbehandlingstjenester, Litauen, et betalingsinstitut med licens fra Litauens centralbank; Resend (Zernonia, Inc.) til udsendelse af e-mails, USA AWS med brug af SCC.</p>',
  '<h3>4.2. Ændringer af underdatabehandlere</h3>',
  '<p>Hvis Tjenesteudbyderen planlægger at tilføje en ny underdatabehandler eller erstatte en eksisterende, informerer Tjenesteudbyderen Kunden via e-mail senest 30 dage før ændringen. Kunden har ret til at gøre indsigelse mod en ny underdatabehandler, hvis der er begrundede databeskyttelsesmæssige årsager. I så fald har Kunden ret til at opsige tjenesteydelsesaftalen.</p>',
  '<h2>5. Registreredes rettigheder</h2>',
  '<h3>5.1. Udøvelse af rettigheder</h3>',
  '<p>Registrerede, dvs. elever og forældre, har følgende rettigheder efter GDPR: ret til indsigt, ret til berigtigelse, ret til sletning, også kaldet retten til at blive glemt, ret til begrænsning, ret til dataportabilitet, ret til indsigelse og ret til at indgive en klage til Litauens statslige databeskyttelsestilsyn (VDAI).</p>',
  '<h3>5.2. Svarfrister og procedurer</h3>',
  '<p>Anmodninger fra registrerede skal først behandles af Kunden som dataansvarlig. Hvis Kunden har brug for teknisk hjælp til at udtrække eller slette oplysninger, kan Kunden kontakte Tjenesteudbyderen via e-mail på info@tutlio.lt. Tjenesteudbyderen besvarer sådanne anmodninger senest inden for 30 dage.</p>',
  '<h2>6. Datasikkerhedsforanstaltninger</h2>',
  '<h3>6.1. Tekniske foranstaltninger</h3>',
  '<p><strong>Kryptering:</strong> TLS 1.3 under overførsel og AES-256 i hvile ved lagring. <strong>Autentifikation:</strong> sikker opbevaring af adgangskoder ved hjælp af bcrypt-hash. <strong>Adgangskontrol:</strong> adskilt adgang til oplysninger ved hjælp af Row-Level Security (RLS). <strong>Sikkerhedskopier:</strong> automatiske daglige sikkerhedskopier, der opbevares i 30 dage. <strong>Overvågning:</strong> overvågning af sikkerhedshændelser og servermålinger.</p>',
  '<h3>6.2. Organisatoriske foranstaltninger</h3>',
  '<p>Uddannelse af medarbejdere og fortrolighedsforpligtelser, hvor alle medarbejdere underskriver en NDA. Begrænsning af adgang: Kun autoriserede medarbejdere har teknisk adgang til infrastrukturen. Hændelseshåndtering: Dokumenterede procedurer for håndtering af sikkerhedsbrud.</p>',
  '<h2>7. Brud på persondatasikkerheden</h2>',
  '<p>Hvis der sker et brud på persondatasikkerheden, underretter Tjenesteudbyderen straks og senest inden for 72 timer Kunden via e-mail, beskriver bruddets karakter, oplyser om de trufne foranstaltninger og giver anbefalinger. Kunden er som dataansvarlig ansvarlig for yderligere underretning af registrerede eller VDAI i overensstemmelse med GDPR.</p>',
  '<h2>8. Internationale dataoverførsler</h2>',
  '<p>De primære personoplysninger opbevares i Den Europæiske Union (AWS eu-central-1). Ved brug af underdatabehandlere, der er registreret i USA, såsom Stripe og Resend, sker dataoverførslen på grundlag af Europa-Kommissionens godkendte standardkontraktbestemmelser (SCC), som sikrer det beskyttelsesniveau, EU kræver.</p>',
  '<h2>9. Revision og kontrol af overholdelse</h2>',
  '<p>Kunden har ret til at anmode om oplysninger om de foranstaltninger til overholdelse af GDPR, som Tjenesteudbyderen anvender. Tjenesteudbyderen forpligter sig til at fremlægge dokumentation. Fysiske revisioner af infrastrukturen kan kun gennemføres efter forudgående aftale, mod dækning af Tjenesteudbyderens omkostninger til revisionsbistand og uden at kompromittere andre kunders fortrolighed.</p>',
  '<h2>10. Aftalens ophør og returnering af oplysninger</h2>',
  '<p>Efter tjenesteydelsesaftalens ophør eller sletning af Kundens konto returnerer Tjenesteudbyderen oplysninger ved at muliggøre eksport i JSON- eller CSV-format. Når overgangsperioden på 30 dage udløber, slettes alle Kundens personoplysninger uigenkaldeligt fra systemer og sikkerhedskopier, bortset fra oplysninger, der skal opbevares efter loven, såsom finansielle transaktioner til bogføringsformål.</p>',
  '<h2>11. Ansvar og erstatning</h2>',
  '<p>Hver part er ansvarlig for skade, der skyldes partens egen overtrædelse af denne DPA og GDPR. Tjenesteudbyderens maksimale økonomiske ansvar som databehandler for overtrædelse af denne DPA er begrænset til de beløb og vilkår, der er fastsat i den primære tjenesteydelsesaftale eller Platformens Brugervilkår under ansvarsbegrænsningen (Liability Cap).</p>',
  '<h2>12. Kontakt</h2>',
  '<p>MB Tutlios kontaktoplysninger vedrørende GDPR og privatliv: E-mail: info@tutlio.lt; Emne: GDPR / Databeskyttelse; Svartid: inden for 5 arbejdsdage.</p>',
  '<h2>13. Afsluttende bestemmelser</h2>',
  '<p>Denne DPA træder i kraft, når Kunden accepterer Platformens Regler eller underskriver tjenesteydelsesaftalen, og er gældende i hele tjenesteperioden. Tjenesteudbyderen kan opdatere denne DPA ved at informere Kunden via e-mail senest 30 dage, før ændringerne træder i kraft. Denne aftale er underlagt Republikken Litauens ret og EU\'s GDPR-krav.</p>',
].join('');

