  'pricing.faq.trialQ': 'Hvordan fungerer den gratis 7-dages prøveperiode?',
  'pricing.faq.trialA': 'Alle nye konti får automatisk 7 dages gratis prøveperiode — ingen kode nødvendig. Du skal indtaste kortoplysninger, men bliver ikke opkrævet i 7 dage. Herefter starter abonnementet automatisk. Du kan opsige når som helst i prøveperioden.',
  'pricing.faq.cancelQ': 'Kan jeg opsige mit abonnement når som helst?',
  'pricing.faq.cancelA': 'Ja! Du kan opsige dit abonnement når som helst via indstillingerne. Hvis du opsiger, forbliver abonnementet aktivt til slutningen af den aktuelle periode — du mister intet.',
