  'orgTutorPolicy.title': 'Interne regler for undervisere',
  'orgTutorPolicy.intro': 'Læs venligst organisationens interne regler, inden du bruger platformen.',
  'orgTutorPolicy.acceptBtn': 'Forstået',
  'orgTutorPolicy.viewBtn': 'Se interne regler',
  'orgTutorPolicy.s1Title': '1. Generelle bestemmelser',
  'orgTutorPolicy.s1Body': 'Disse regler regulerer din brug af Tutlio-platformen ("Platformen") som lærer eller underviser ("Underviseren"). Du er inviteret til at bruge Platformen af den uddannelsesorganisation, skole eller tutorcenter, du repræsenterer ("Organisationen"). Platformen drives og vedligeholdes teknisk af MB Tutlio. Ved at bruge din konto accepterer du disse Regler og Privatlivspolitikken.',
  'orgTutorPolicy.s2Title': '2. Kontostyring og tidsplaner',
  'orgTutorPolicy.s2Intro': 'Platformen er designet, så du ikke behøver at bruge tid på at koordinere lektionstider med elever.',
  'orgTutorPolicy.s2Link': 'Unikt link: Du tildeles et personligt bookinglink til lektioner (baseret på de fag, du underviser i), som elever bruger til at planlægge lektioner.',
  'orgTutorPolicy.s2Calendar': 'Kalendersynkronisering: Din tilgængelighed afhænger direkte af din Google Kalender-integration (tovejssynkronisering). Du er personligt ansvarlig for, at den ledige tid i din kalender er korrekt og opdateret. Platformen tillader ikke elever at booke tider, der er markeret som optaget i din kalender.',
  'orgTutorPolicy.s2Security': 'Kontosikkerhed: Din konto er personlig. Du skal opbevare dine loginoplysninger sikkert og ikke dele dem med tredjeparter.',
  'orgTutorPolicy.s3Title': '3. Aflysning af lektioner og venteliste',
  'orgTutorPolicy.s3Intro': 'Platformen hjælper dig med at udnytte din tidsplan optimalt og undgå tomme pladser:',
  'orgTutorPolicy.s3Auto': 'Hvis en elev aflyser en lektion, sender Platformen automatisk en besked (SMS/e-mail) til andre elever på din venteliste og tilbyder den ledige tid. Der kræves ingen yderligere handling fra din side.',
  'orgTutorPolicy.s3Rules': 'Regler for aflysning af lektioner (hvor lang tid i forvejen man kan aflyse, konsekvenser) fastsættes af din Organisation.',
  'orgTutorPolicy.s4Title': '4. Økonomi og betalinger',
  'orgTutorPolicy.s4Intro': 'Du behøver ikke at bekymre dig om fakturering eller opkrævning af betalinger fra forældre:',
  'orgTutorPolicy.s4Advance': 'Alle elevers (eller forældres) betalinger for dine lektioner opkræves forud via Platformen og overføres direkte til din Organisation.',
  'orgTutorPolicy.s4Confirmed': 'Du afholder kun en lektion, når den er bekræftet i systemet (dvs. betalingen er allerede trukket).',
  'orgTutorPolicy.s4Contact': 'Vedrørende din løn, udbetalingsplan og andre økonomiske spørgsmål, kontakt venligst din Organisations administrator direkte. MB Tutlio udfører ingen direkte økonomiske transaktioner med Undervisere.',
  'orgTutorPolicy.s5Title': '5. Beskyttelse af elevdata (GDPR)',
  'orgTutorPolicy.s5Intro': 'Som Underviser har du adgang til elevers personoplysninger, interne noter og undervisningsmaterialer. Du forpligter dig til at:',
  'orgTutorPolicy.s5Use': 'Bruge disse data udelukkende til at organisere og afholde lektioner.',
  'orgTutorPolicy.s5NoCopy': 'Ikke kopiere, eksportere eller distribuere elevers eller forældres kontaktoplysninger uden for Platformen.',
  'orgTutorPolicy.s5Notes': 'Beskytte Organisationens interne optegnelser (noter om elevens fremskridt), som kun er synlige for dig og Organisationens administration, ikke for elever eller forældre.',
  'orgTutorPolicy.s5Termination': 'Når dit arbejdsforhold med Organisationen ophører, tilbagekaldes din adgang til disse data øjeblikkeligt.',
  'orgTutorPolicy.s6Title': '6. Teknisk drift og ansvarsbegrænsning',
  'orgTutorPolicy.s6Body': 'Brug af Platformen til ulovlige formål, distribution af ondsindede links i undervisningsmaterialer eller anden forstyrrelse af systemet er forbudt. MB Tutlio sikrer Platformens drift og tekniske vedligeholdelse, men påtager sig intet ansvar for forstyrrelser forårsaget af din internetforbindelse, enhedsfejl eller forkert konfigurerede Google Kalender-indstillinger.',
  'orgTutorPolicy.s7Title': '7. Support og kontakt',
  'orgTutorPolicy.s7Org': 'Ved spørgsmål om lektionsplaner, løn, elevtildeling eller arbejdsorganisering, kontakt din Organisations administrator.',
  'orgTutorPolicy.s7Tech': 'Ved tekniske fejl på Platformen (kalendersynkronisering virker ikke, du modtager ikke beskeder), informer Organisationens administrator, som vil kontakte Tutlios tekniske supportteam.',

