  'feature.cancellation.pageTitle': 'Afbudsregler og gebyrer for sent afbud for undervisere',
  'feature.cancellation.pageDesc': 'Angiv klare afbudsfrister og automatiske gebyrer for sent afbud. Når elever melder afbud, går ledige tider direkte til din venteliste.',
  'feature.cancellation.detailsTitle': 'Sådan fungerer afbudsregler',
  'feature.cancellation.deadlines': 'Afbudsfrister',
  'feature.cancellation.deadlinesDesc': 'Angiv, hvor lang tid i forvejen elever skal melde afbud (f.eks. 24 timer før lektionen) for at undgå et afbudsgebyr.',
  'feature.cancellation.fees': 'Automatiske gebyrer for sent afbud',
  'feature.cancellation.feesDesc': 'Angiv et procentgebyr (f.eks. 50 % af lektionsprisen), der automatisk pålægges, når en elev melder afbud for sent.',
  'feature.cancellation.transparency': 'Klar kommunikation med elever',
  'feature.cancellation.transparencyDesc': 'Eleverne ser din afbudspolitik med det samme ved booking. Ingen overraskelser — kun professionelle, fair regler.',
  'feature.cancellation.waitlistLink': 'Integration med venteliste',
  'feature.cancellation.waitlistLinkDesc': 'Aflyste tider tilbydes straks til elever på ventelisten, så din kalender forbliver fuld, og din indtjening beskyttes.',
  'feature.cancellation.faq.howSetQ': 'Hvordan opsætter jeg afbudsregler?',
  'feature.cancellation.faq.howSetA': 'Gå til dine lektionsindstillinger og angiv afbudsfristen (timer før lektionen) og procentsatsen for gebyret ved sent afbud. Systemet håndhæver dem automatisk.',
  'feature.cancellation.faq.refundQ': 'Hvad sker der med afbudsgebyret?',
  'feature.cancellation.faq.refundA': 'Gebyrer for sent afbud beregnes automatisk og lægges til elevens saldo. Du kan følge alle gebyrer i dit økonomioverblik.',
  'feature.cancellation.faq.studentSeeQ': 'Ser eleverne afbudspolitikken?',
  'feature.cancellation.faq.studentSeeA': 'Ja, dine afbudsvilkår vises for eleverne under bookingen, så de kender reglerne, før de bekræfter.',
  'feature.comments.pageTitle': 'Lektionsnoter, kommentarer og fildeling for undervisere',
  'feature.comments.pageDesc': 'Vedhæft noter, lektier og filer til enkelte lektioner. Opbyg en komplet lektionshistorik, som elever og forældre kan tilgå når som helst.',
  'feature.comments.detailsTitle': 'Sådan fungerer lektionsnoter',
  'feature.comments.lessonNotes': 'Noter pr. lektion',
  'feature.comments.lessonNotesDesc': 'Tilføj private eller delte noter til enhver lektion — hold styr på, hvad der blev gennemgået, elevens fremskridt og næste skridt.',
  'feature.comments.fileSharing': 'Filvedhæftninger',
  'feature.comments.fileSharingDesc': 'Upload opgaveark, lektie-PDF\'er eller studiemateriale og vedhæft dem direkte til en lektion for nem adgang.',
  'feature.comments.history': 'Komplet lektionshistorik',
  'feature.comments.historyDesc': 'Hver note og fil er knyttet til den lektion, den hører til, og skaber en søgbar tidslinje over hver elevs læringsrejse.',
  'feature.comments.parentAccess': 'Synlighed for forældre',
  'feature.comments.parentAccessDesc': 'Forældre kan se delte lektionsnoter og filer i deres portal og holdes informeret om deres barns fremskridt.',
  'feature.comments.faq.whoSeesQ': 'Hvem kan se lektionsnoter?',
  'feature.comments.faq.whoSeesA': 'Du vælger, hvad du vil dele. Noter kan være private (kun for underviseren) eller deles med eleven og dennes forælder.',
  'feature.comments.faq.fileTypesQ': 'Hvilke filtyper kan jeg uploade?',
  'feature.comments.faq.fileTypesA': 'Du kan uploade PDF\'er, billeder og almindelige dokumentformater. Filerne gemmes sikkert og er tilgængelige fra enhver enhed.',
  'feature.comments.faq.storageQ': 'Er der en lagringsgrænse?',
  'feature.comments.faq.storageA': 'Alle planer inkluderer rigeligt fillagring. Der er ingen grænser pr. fil — vedhæft så mange materialer, du har brug for.',
